if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php');verify_csrf();$id=(int)($_POST['vehicle_id']??0);$s=$pdo->prepare('SELECT * FROM vehicles WHERE id=?');$s->execute([$id]);$v=$s->fetch();if(!$v)redirect('index.php');$u=current_user();$allowed=has_role(['officer','admin']) || ((int)$v['owner_user_id']===(int)$u['id']) || mb_strtolower($v['owner_email'])===mb_strtolower($u['email']);if(!$allowed){http_response_code(403);exit('Недостаточно прав.');}
